local root=assert(app.params['root']);local pc=app.pixelColor
local meta=json.decode(assert(io.open(root..'/Source/pose_metadata.json','r')):read('*a'));local pal=Palette(27);pal:setColor(0,Color{r=0,g=0,b=0,a=0})
local function lin(v)v=v/255;if v<=.04045 then return v/12.92 else return((v+.055)/1.055)^2.4 end end
local function lab(r,g,b)r,g,b=lin(r),lin(g),lin(b);local l=(.4122214708*r+.5363325363*g+.0514459929*b)^(1/3);local m=(.2119034982*r+.6806995451*g+.1073969566*b)^(1/3);local s=(.0883024619*r+.2817188376*g+.6299787005*b)^(1/3);return{.2104542553*l+.793617785*m-.0040720468*s,1.9779984951*l-2.428592205*m+.4505937099*s,.0259040371*l+.7827717662*m-.808675766*s}end
local colors,pixels={},{};for i,h in ipairs(meta.palette)do local r,g,b=tonumber(h:sub(1,2),16),tonumber(h:sub(3,4),16),tonumber(h:sub(5,6),16);pixels[i]=pc.rgba(r,g,b,255);colors[i]=lab(r,g,b);pal:setColor(i,Color{r=r,g=g,b=b,a=255})end
local cache={};local function mapped(p)if pc.rgbaA(p)<128 then return 0 end;if cache[p]then return cache[p]end;local c=lab(pc.rgbaR(p),pc.rgbaG(p),pc.rgbaB(p));local best,ii=1e9,1;for i,v in ipairs(colors)do local d=(c[1]-v[1])^2*1.2+(c[2]-v[2])^2+(c[3]-v[3])^2;if d<best then best,ii=d,i end end;cache[p]=pixels[ii];return pixels[ii]end
local function bounds(img)local bx,by,ex,ey=img.width,img.height,-1,-1;for y=0,img.height-1 do for x=0,img.width-1 do if pc.rgbaA(img:getPixel(x,y))>=128 then bx=math.min(bx,x);by=math.min(by,y);ex=math.max(ex,x);ey=math.max(ey,y)end end end;return{bx,by,ex-bx+1,ey-by+1}end
local full=Image{fromFile=root..'/Source/Generated/sundeok_redesign_full.png'};local b=bounds(full);local ratio=112/b[4];local tw=math.floor(b[3]*ratio+.5);local ox=(120-tw)//2
local function sample(img,b,ow,oh,ox,oy,canvasW,canvasH)local out=Image(canvasW,canvasH,ColorMode.RGB);for y=0,oh-1 do for x=0,ow-1 do local sx=b[1]+math.min(b[3]-1,math.floor((x+.5)*b[3]/ow));local sy=b[2]+math.min(b[4]-1,math.floor((y+.5)*b[4]/oh));out:drawPixel(ox+x,oy+y,mapped(img:getPixel(sx,sy)))end end;return out end
local full120=sample(full,b,tw,112,ox,6,120,120);full120:saveAs(root..'/Source/redesign_full_120.png')
local body=Image{fromFile=root..'/Source/Generated/sundeok_redesign_body.png'};assert(body.width==full.width and body.height==full.height);local body120=sample(body,b,tw,112,ox,6,120,120);body120:saveAs(root..'/Source/redesign_body_120.png')
local gun=Image{fromFile=root..'/Source/Generated/sundeok_shotgun_generated.png'};local gb=bounds(gun);local gw=78;local gh=math.floor(gb[4]*gw/gb[3]+.5);local gun70=sample(gun,gb,gw,gh,0,0,gw,gh);gun70:saveAs(root..'/Source/redesign_shotgun_sampled.png')
for _,item in ipairs({{'full',full120},{'body',body120},{'shotgun',gun70}})do local s=Sprite(item[2].width,item[2].height,ColorMode.RGB);s:setPalette(pal);s:newCel(s.layers[1],1,item[2]);s.layers[1].name='Sampled_26Color_Reference';s:saveAs(root..'/Source/redesign_'..item[1]..'.aseprite');s:close()end
local report={full_source_size={full.width,full.height},source_bounds=b,target_size={tw,112},target_origin={ox,6},gun_source_size={gun.width,gun.height},gun_bounds=gb,gun_target_size={gw,gh},palette_path='Export/sundeok_26.gpl',method='Built-in ImageGen redesign; native Aseprite nearest sampling + Oklab palette mapping; alpha threshold 128'};local f=assert(io.open(root..'/Source/redesign_sampling.json','w'));f:write(json.encode(report));f:close();print(json.encode(report))
